// Oracle ball: ask it a question, shake the frame, and an answer floats up in
// its window. Turning the frame face down and back up asks again too, and so
// do a tap and the Action key, which is how a frame without an accelerometer
// asks. The answer is kept in the scene's state, so it stays on e-paper
// until the next question. On a fast screen (not an ESP32's) the answer rises
// out of the dark over a second.

const ANSWERS = [
  'Yes',
  'Without a doubt',
  'Count on it',
  'The signs say yes',
  'Most likely',
  'It looks good',
  'Yes, in time',
  'Go for it',
  'Probably',
  'Ask again later',
  'Too soon to tell',
  'Hard to say now',
  'Sleep on it',
  'Concentrate and ask again',
  'Maybe',
  'Not this time',
  'Unlikely',
  'The signs say no',
  'Better not',
  'No',
]

// When the answer showing was asked for: it rises for a second after.
let askedAt = 0
let wasFaceDown = false

const hasAccelerometer = (app: any) => app.frame.accelerometer === true

function ask(app: any) {
  const last = Number(app.state.answer)
  let next = Math.floor(Math.random() * ANSWERS.length)
  if (next === last) next = (next + 1 + Math.floor(Math.random() * (ANSWERS.length - 1))) % ANSWERS.length
  frameos.setState('answer', next)
  frameos.setState('asked', Number(app.state.asked || 0) + 1)
  askedAt = Date.now()
}

/** Words broken into lines of about `width` letters. */
function lines(text: string, width: number): string[] {
  const out: string[] = []
  let line = ''
  for (const word of text.split(' ')) {
    if (line && (line + ' ' + word).length > width) {
      out.push(line)
      line = word
    } else line = line ? line + ' ' + word : word
  }
  if (line) out.push(line)
  return out
}

export function get(app: any, context: any) {
  const W = context.imageWidth || app.frame.width
  const H = context.imageHeight || app.frame.height
  const round = context.round === true
  const fast = app.frame.fast ?? !app.frame.paper
  const S = Math.min(W, H)
  const cx = W / 2
  const hint = round ? 0 : Math.max(16, Math.round(S * 0.05))
  const cy = round ? H / 2 : (H - hint * 1.6) / 2
  const R = round ? S / 2 - 2 : Math.min(W, H - hint * 3) * 0.46
  const win = R * 0.5

  const index = app.state.answer
  const answered = index !== undefined && index !== null && index !== '' && ANSWERS[Number(index)] !== undefined
  const text = answered ? ANSWERS[Number(index)] : hasAccelerometer(app) ? 'Ask, then shake' : 'Ask, then tap'
  const words = lines(text.toUpperCase(), 10)
  // Rising: a second from dark to bright on a fast screen. Not on an ESP32,
  // whose frame waits a whole second between pictures unless the scene
  // animates all the time (its refreshInterval under a second).
  const age = Date.now() - askedAt
  const rise = fast && !app.frame.embedded && answered && age < 1000 ? age / 1000 : 1
  if (fast && rise < 1) frameos.setNextSleep(0.05)

  const paper = !fast
  // A triangle in the window, point down, the words on it: it grows out of
  // the dark as it rises, and stays inside the window.
  const tri = win * 0.92 * (0.55 + 0.45 * rise)
  const ty = cy
  const p1 = `${cx - tri * 0.866},${ty - tri * 0.5}`
  const p2 = `${cx + tri * 0.866},${ty - tri * 0.5}`
  const p3 = `${cx},${ty + tri}`
  const fontSize = Math.round(win * (words.length > 2 ? 0.17 : 0.2) * (0.55 + 0.45 * rise))
  const lineH = fontSize * 1.1
  const top = ty - tri * 0.22 - ((words.length - 1) * lineH) / 2
  const triColor = paper ? '#ffffff' : rise < 1 ? mix('#06102e', '#1f3fbf', rise) : '#1f3fbf'
  const wordColor = paper ? '#000000' : rise < 1 ? mix('#06102e', '#e9eeff', rise) : '#e9eeff'

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <defs>
        <radialGradient id="shine" gradientUnits="userSpaceOnUse" cx={cx - R * 0.3} cy={cy - R * 0.4} r={R * 1.5}>
          <stop offset="0" stopColor="#4a4f5c" />
          <stop offset="0.45" stopColor="#111318" />
          <stop offset="1" stopColor="#000000" />
        </radialGradient>
      </defs>
      <rect x={0} y={0} width={W} height={H} fill={paper ? '#ffffff' : round ? '#000000' : '#20242c'} />
      <circle cx={cx} cy={cy} r={R} fill={paper ? '#000000' : 'url(#shine)'} />
      <circle cx={cx} cy={cy} r={win} fill={paper ? '#000000' : '#04081a'} stroke={paper ? '#ffffff' : '#2b2f3a'} strokeWidth={Math.max(2, R * 0.025)} />
      {answered ? (
        <polygon points={`${p1} ${p2} ${p3}`} fill={triColor} />
      ) : null}
      {words.map((word, i) => (
        <text x={cx} y={(answered ? top : cy - ((words.length - 1) * lineH) / 2) + i * lineH + fontSize * 0.35}
          fontSize={answered ? fontSize : Math.round(win * 0.15)} fontWeight="bold" textAnchor="middle"
          fill={answered ? wordColor : paper ? '#ffffff' : '#9aa3c7'}>
          {word}
        </text>
      ))}
      {round ? null : (
        <text x={cx} y={H - hint * 0.9} fontSize={hint} textAnchor="middle" fill={paper ? '#000000' : '#9aa3c7'}>
          {hasAccelerometer(app) ? 'Shake the frame, or tap, for an answer' : 'Tap for an answer'}
        </text>
      )}
    </svg>
  )
}

function mix(a: string, b: string, t: number): string {
  const pa = parseInt(a.slice(1), 16)
  const pb = parseInt(b.slice(1), 16)
  let out = '#'
  for (const shift of [16, 8, 0]) {
    const va = (pa >> shift) & 255
    const vb = (pb >> shift) & 255
    out += Math.round(va + (vb - va) * t).toString(16).padStart(2, '0')
  }
  return out
}

export function onEvent(app: any, context: any) {
  const e = context.event
  const p = context.payload || {}
  if (e === 'orientation') {
    // Face down and back up asks again, as the toy is used.
    if (p.position === 'faceDown') {
      wasFaceDown = true
      return false
    }
    if (!wasFaceDown) return false
    wasFaceDown = false
    ask(app)
    return true
  }
  if (e === 'shake' || e === 'tap' || (e === 'button' && p.action === 'press') ||
      (e === 'keyDown' && (p.code === 'Space' || p.code === 'Enter'))) {
    ask(app)
    return true
  }
  return false
}
